class Shape:
    def __init__(self, name):
        self.name = name

    def area(self):
        return f"Area method not implemented for {self.name}."

    def perimeter(self):
        return f"Perimeter method not implemented for {self.name}."


class Circle(Shape):
    PI = 3.14

    def __init__(self, name, radius):
        super().__init__(name)
        self.radius = radius

    def area(self):
        return self.PI * (self.radius ** 2)

    def perimeter(self):
        return 2 * self.PI * self.radius


class Rectangle(Shape):
    def __init__(self, name, width, height):
        super().__init__(name)
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)


def calculate_and_display(shapes_list):
    print("\n--- Polymorphic Calculation ---")
    for shape in shapes_list:
        print(f"\nShape: {shape.name}")
        # Area and Perimeter methods are called polymorphically
        print(f"Area: {shape.area():.2f}") 
        print(f"Perimeter: {shape.perimeter():.2f}")


circle = Circle('My Circle', 5)
rect = Rectangle('My Rectangle', 10, 5)

shapes = [circle, rect]
calculate_and_display(shapes)
